    public void testGenerateXmlDeclaration() {
        // Arrange
        String input = "<!-- This is a comment -->";

        // Act
        XmlDeclaration xmlDeclaration = new XmlDeclaration(input);

        // Assert
        assertTrue(xmlDeclaration.isXmlDeclarationData(input));
    }

